svg.title:
\boxed{\begin{aligned}
 \text{amortized update factor}
    &\le \exp O(U^{6/7}h^{1/7}),\\
 \text{distance stretch}
    &\le \exp O(U^{5/7}h^{2/7}),\\
 \text{distance query time}&\le\mathrm{polylog}N,
 \qquad U=\log_2(N+4),\quad h=\lceil\log_2(U+4)\rceil.
\end{aligned}}                                                    \tag{P1}
